import{c as s,Q as e,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Session Insights — 評估即交付：harness 平台期的「完整評估再執行」紀律","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-20-session-insights-evaluation-as-deliverable.md","filePath":"research/reports/2026-06-20-session-insights-evaluation-as-deliverable.md","lastUpdated":1785909234000}'),o={name:"research/reports/2026-06-20-session-insights-evaluation-as-deliverable.md"};function n(i,t,l,d,h,g){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="session-insights-—-評估即交付-harness-平台期的「完整評估再執行」紀律" tabindex="-1">Session Insights — 評估即交付：harness 平台期的「完整評估再執行」紀律 <a class="header-anchor" href="#session-insights-—-評估即交付-harness-平台期的「完整評估再執行」紀律" aria-label="Permalink to &quot;Session Insights — 評估即交付：harness 平台期的「完整評估再執行」紀律&quot;">​</a></h1><blockquote><p><strong>日期</strong>: 2026-06-20 <strong>來源</strong>: Session（claude/anthropic-claude-code-expertise-5myrpg branch；PR #692 squash→main 7804201） <strong>類型</strong>: Session Learning Report（meta — 過程模式，非研究內容；研究內容見本 session 5 份報告） <strong>Topic</strong>: Evaluation-as-Deliverable · 功能級 Gap 驗證 · 構念對齊 · 反向 anti-hack · 平台期信號</p></blockquote><hr><h2 id="_0-tl-dr" tabindex="-1">0. TL;DR <a class="header-anchor" href="#_0-tl-dr" aria-label="Permalink to &quot;0. TL;DR&quot;">​</a></h2><p>本 session 從「分析 Anthropic 400K 研究」起，演變為<strong>對 workspace 候選改動的連續嚴格評估</strong>。最反直覺的結果：<strong>多數產出是「不做」的決定</strong>——3 輪正式評估（TIER B / 4 缺口 / autoload 雙候選）<strong>全數收斂到「既有 harness 已覆蓋」或「前提不成立」</strong>，淨落地僅 3 個小項。</p><p>核心 meta-insight：<strong>在高成熟度 harness 上，「完整評估」本身就是交付物</strong>——它擋下的冗餘/有害/投機變更，價值高於勉強擠出的新規則。本報告萃取此過程的 <strong>5 個可複用模式</strong> + <strong>4 條 Lesson</strong>。</p><hr><h2 id="_1-核心任務與結果-簡述" tabindex="-1">1. 核心任務與結果（簡述） <a class="header-anchor" href="#_1-核心任務與結果-簡述" aria-label="Permalink to &quot;1. 核心任務與結果（簡述）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>階段</th><th>產出</th><th>落地</th></tr></thead><tbody><tr><td>研究</td><td>5 份深度報告（400K expertise / 週報0618 / HarnessX-DecentMem / TIER B / 覆蓋稽核）</td><td>—</td></tr><tr><td>執行</td><td>TIER A 3 小項（grid DeepSWE/Fable-G7、fable access GOTCHA、HarnessX 九維 lens）</td><td>✅</td></tr><tr><td>評估擋下</td><td>TIER B(3) + 4 缺口 + autoload(2)</td><td><strong>全 DEFER/DROP/DISCARD</strong></td></tr><tr><td>交付</td><td>PR #692 squash→main；healthcheck 126/0 FAIL</td><td>✅ merged</td></tr></tbody></table><p><strong>量化軌跡</strong>：候選改動 <strong>12 項評估 → 3 落地（25%）</strong>；其餘 9 項全經 grep 接地 + fable-pilot 反向審閱後<strong>正確擋下</strong>。</p><hr><h2 id="_2-可複用模式-本-session-的真正資產" tabindex="-1">2. 可複用模式（本 session 的真正資產） <a class="header-anchor" href="#_2-可複用模式-本-session-的真正資產" aria-label="Permalink to &quot;2. 可複用模式（本 session 的真正資產）&quot;">​</a></h2><h3 id="_2-1-評估即交付-evaluation-as-deliverable" tabindex="-1">2.1 評估即交付（Evaluation-as-Deliverable） <a class="header-anchor" href="#_2-1-評估即交付-evaluation-as-deliverable" aria-label="Permalink to &quot;2.1 評估即交付（Evaluation-as-Deliverable）&quot;">​</a></h3><p>3 輪評估連續 0 執行<strong>不是失敗，是高成熟度信號</strong>。每輪評估擋下的是：</p><ul><li>TIER B：對既有功能<strong>重複建設</strong>（B2 harness-loop / B3 失敗分類）</li><li>4 缺口：<strong>有害</strong>（GAP-1 強制 haiku 癱瘓委派）+ <strong>證偽</strong>（GAP-3 routine 不用 Fable）</li><li>autoload：<strong>誤接地</strong>（A）+ <strong>goodhart</strong>（B）</li></ul><p>→ 在平台期 harness 上，「不做」需要與「做」同等的證據鏈。把評估寫成 report-only 報告（本 session 5 份中 3 份是評估）= 讓「不做」可追溯、可複查。</p><h3 id="_2-2-功能級-vs-字串級-gap-驗證-lesson-f-本-session-最高頻陷阱" tabindex="-1">2.2 功能級 vs 字串級 Gap 驗證（Lesson-F，本 session 最高頻陷阱） <a class="header-anchor" href="#_2-2-功能級-vs-字串級-gap-驗證-lesson-f-本-session-最高頻陷阱" aria-label="Permalink to &quot;2.2 功能級 vs 字串級 Gap 驗證（Lesson-F，本 session 最高頻陷阱）&quot;">​</a></h3><p>subagent 稽核反覆把「字串不存在」誤報為「功能缺口」：</p><table tabindex="0"><thead><tr><th>假缺口</th><th>字串級判定</th><th>功能級真相</th></tr></thead><tbody><tr><td>B3 ETCLOVG</td><td><code>grep ETCLOVG</code>=空 → NOT-DONE</td><td>既有 4 層失敗歸因已覆蓋 6/7 類</td></tr><tr><td>B2 harness-loop F1</td><td>比對到 reactive gate</td><td>APPLY 行已有 proactive 檢查</td></tr><tr><td>GAP-1 subagent 防護</td><td><code>deny</code> 無此規則</td><td>2026-06-07 已裁決為 user-tradeoff + 遞迴 harness 不可能</td></tr><tr><td>GAP-3 routine fallback</td><td>無 fallback 宣告</td><td>routine 全用 Sonnet 不用 Fable，無 deadlock</td></tr></tbody></table><p>→ <strong>協議</strong>：subagent 提報的 gap，主對話必須升級為功能級重驗——「既有結構是否已覆蓋此<strong>功能</strong>」+「此前提是否在歷史報告<strong>已裁決</strong>」，不止 grep 關鍵字。</p><h3 id="_2-3-構念對齊-論文接地前必驗「量的是同一件事嗎」-lesson-h" tabindex="-1">2.3 構念對齊：論文接地前必驗「量的是同一件事嗎」（Lesson-H） <a class="header-anchor" href="#_2-3-構念對齊-論文接地前必驗「量的是同一件事嗎」-lesson-h" aria-label="Permalink to &quot;2.3 構念對齊：論文接地前必驗「量的是同一件事嗎」（Lesson-H）&quot;">​</a></h3><p>autoload 候選 A 想把 400K 研究的 expertise 洞見落地為「agent 自評自身領域專業度」。但研究原文量的是 <strong>USER 專業度（Claude 從 transcript 觀察）</strong>——<strong>偷換構念</strong>：研究權威<strong>不背書</strong>任意衍生主張。</p><p>→ 論文洞見入 auto-load 前的閘門：① 研究量的構念 = 我要落地的構念？② 轉移條件成立？（呼應 HarnessX/DecentMem 評估的同一紀律）</p><h3 id="_2-4-分類系統增殖反模式" tabindex="-1">2.4 分類系統增殖反模式 <a class="header-anchor" href="#_2-4-分類系統增殖反模式" aria-label="Permalink to &quot;2.4 分類系統增殖反模式&quot;">​</a></h3><p>本 session 險些並存<strong>三套</strong> harness 分類：HMF 7D（元件類型，既有）/ HarnessX 9D（行為功能，新加）/ ETCLOVG（失敗類別，提案）。</p><ul><li>HarnessX 9D <strong>正確落地</strong>（標 <code>TODO(conflict)</code> 與 HMF 7D 區隔為 cross-check lens，不混用）</li><li>ETCLOVG <strong>正確擋下</strong>（與既有 4 層失敗歸因重疊）</li></ul><p>→ 新分類框架入庫前問：「與既有 N 套分類是否同軸？」同軸 = 增殖（DROP）；正交 = 須顯式標界線防混用。</p><h3 id="_2-5-反向-anti-hack-fable-pilot-的對稱用法" tabindex="-1">2.5 反向 anti-hack（fable-pilot 的對稱用法） <a class="header-anchor" href="#_2-5-反向-anti-hack-fable-pilot-的對稱用法" aria-label="Permalink to &quot;2.5 反向 anti-hack（fable-pilot 的對稱用法）&quot;">​</a></h3><p>本 session 把 fable-pilot 的 anti-hack <strong>反向</strong>使用：常規問「是否假裝完成」；本 session 問「<strong>是否假裝『已存在』以逃避該做的工作</strong>」。每個 DROP/DISCARD 裁決都經此反向審——驗證「既有覆蓋」非省事藉口（特地找被連帶棄掉的 kernel，結果皆已被既有條文更佳覆蓋）。</p><p>→ 驗證紀律是對稱的：false-done 與 false-already-exists 都是 hack，都需 rejected-claims ledger。</p><hr><h2 id="_3-平台期信號與行動建議" tabindex="-1">3. 平台期信號與行動建議 <a class="header-anchor" href="#_3-平台期信號與行動建議" aria-label="Permalink to &quot;3. 平台期信號與行動建議&quot;">​</a></h2><p><strong>信號</strong>：3 輪評估連續收斂到「既有已覆蓋」+ EVOLUTION-QUEUE 清空（0 pending）+ healthcheck 長期 126/0 FAIL。</p><p><strong>判讀</strong>：workspace harness 處於<strong>高成熟度平台期</strong>——真正待落地的有價值改動已清空。</p><p><strong>行動建議</strong>：</p><ul><li>✅ <strong>等新研究訊號</strong>（新 daily-research / 新論文）再觸發 cycle，不為動而動製造候選（呼應 RATCHET 2026-05-31i「不為 byte slot 製造規則」）</li><li>✅ 候選評估維持<strong>反向 anti-hack</strong> + 功能級重驗 + 構念對齊三閘</li><li>⚠️ 警惕「agentic laziness 的反面」——<strong>過度產出候選</strong>也是一種 drift（為證明價值而擠規則）</li></ul><hr><h2 id="_4-lessons-彙整-本-session-入-memory" tabindex="-1">4. Lessons 彙整（本 session 入 MEMORY） <a class="header-anchor" href="#_4-lessons-彙整-本-session-入-memory" aria-label="Permalink to &quot;4. Lessons 彙整（本 session 入 MEMORY）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lesson</th><th>內容</th><th>防範</th></tr></thead><tbody><tr><td><strong>E</strong></td><td>落地前必 grep 既有同類框架（HarnessX 險與 HMF 7D 衝突）</td><td>「缺口」宣稱二次驗證既有結構</td></tr><tr><td><strong>F</strong></td><td>subagent「NOT-DONE」是字串級；值得做須功能級重驗</td><td>既有結構是否覆蓋該<strong>功能</strong></td></tr><tr><td><strong>G</strong></td><td>subagent 的「新缺口」可能是<strong>既有已裁決項</strong>（GAP-1=2026-06-07）</td><td>親驗須 grep 歷史報告決議</td></tr><tr><td><strong>H</strong></td><td>論文洞見落地前驗<strong>構念對齊</strong>（400K 量 USER 非 agent 自評）</td><td>研究權威不背書任意衍生</td></tr></tbody></table><hr><h2 id="_5-與既有-harness-紀律的關係" tabindex="-1">5. 與既有 harness 紀律的關係 <a class="header-anchor" href="#_5-與既有-harness-紀律的關係" aria-label="Permalink to &quot;5. 與既有 harness 紀律的關係&quot;">​</a></h2><p>本 session 的模式<strong>不是新規則</strong>，而是既有紀律的<strong>密集應用實例</strong>：</p><ul><li><code>unverified_success</code> 閘門 → 反向擴展為 false-already-exists 也需親驗</li><li>core.md「不為未來可能鋪設」→ 平台期「不為動而動製造候選」</li><li>PROPOSE「Rule of 3」→ 評估候選時的 anti-over-engineering 主軸</li></ul><p>→ 故本報告<strong>不提議新 auto-load 規則</strong>（自身即遵守平台期紀律）；價值在<strong>記錄可複用的評估過程</strong>供下次同類 cycle 注入。</p><hr><p><em>方法：本報告為 session meta-反思（RECORD 階段產物）。所有引用的裁決/數字可溯本 session 5 份報告 + MEMORY Lesson E/F/G/H + PR #692。不提議規則變更。</em></p>',46)])])}const u=s(o,[["render",n]]);export{p as __pageData,u as default};
